const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  const getInfo = (eeObj) => new Promise((resolve, reject) => eeObj.getInfo((v, e) => e ? reject(e) : resolve(v)));

  const region = ee.Geometry.Point([37.158, 36.206]).buffer(15000); // Aleppo ~15 km buffer

  const primaryColId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG';
  const fallbackColId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG';

  async function getYearStats(year) {
    const start = ee.Date.fromYMD(year, 1, 1);
    const end = ee.Date.fromYMD(year + 1, 1, 1);

    let col = ee.ImageCollection(primaryColId).filterDate(start, end).select(['avg_rad']);
    let n = await getInfo(col.size());
    let usedColId = primaryColId;

    if (!n || n === 0) {
      const col2 = ee.ImageCollection(fallbackColId).filterDate(start, end).select(['avg_rad']);
      const n2 = await getInfo(col2.size());
      if (!n2 || n2 === 0) {
        return { empty: true, usedColId: null, nImages: 0, mean: null, pixels: 0 };
      }
      col = col2;
      n = n2;
      usedColId = fallbackColId;
    }

    const yearImg = col.mean().rename('avg_rad');
    const reducer = ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true });
    const dict = await getInfo(yearImg.reduceRegion({
      reducer: reducer,
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }));

    const mean = dict ? dict['avg_rad_mean'] : null;
    const pixels = dict ? dict['avg_rad_count'] : 0;

    return { empty: false, usedColId, nImages: n, mean, pixels };
  }

  try {
    const stats2012 = await getYearStats(2012);
    const stats2016 = await getYearStats(2016);

    if (stats2012.empty || stats2016.empty) {
      console.log('Region: Aleppo (15 km buffer)');
      console.log(`2012 Images: ${stats2012.nImages || 0}`);
      console.log(`2016 Images: ${stats2016.nImages || 0}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    if ((stats2012.pixels || 0) === 0 || (stats2016.pixels || 0) === 0) {
      console.log('Region: Aleppo (15 km buffer)');
      console.log(`2012 Images: ${stats2012.nImages}, Pixels: ${stats2012.pixels || 0}`);
      console.log(`2016 Images: ${stats2016.nImages}, Pixels: ${stats2016.pixels || 0}`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }

    const m2012 = stats2012.mean;
    const m2016 = stats2016.mean;
    if (m2012 === null || m2016 === null || !isFinite(m2012) || !isFinite(m2016)) {
      console.log('Region: Aleppo (15 km buffer)');
      console.log(`2012 Images: ${stats2012.nImages}, Pixels: ${stats2012.pixels}, Mean_rad: ${m2012}`);
      console.log(`2016 Images: ${stats2016.nImages}, Pixels: ${stats2016.pixels}, Mean_rad: ${m2016}`);
      console.log('C3: Calculation Failure (Result is `None`, `NaN`, or invalid).');
      return;
    }

    const diff = m2016 - m2012;
    const pct = m2012 !== 0 ? (diff / m2012) * 100 : null;

    console.log(`Dataset: ${stats2012.usedColId}`);
    console.log(`2012 Images: ${stats2012.nImages}, Pixels: ${stats2012.pixels}, Mean_rad: ${m2012.toFixed(2)}`);
    console.log(`2016 Images: ${stats2016.nImages}, Pixels: ${stats2016.pixels}, Mean_rad: ${m2016.toFixed(2)}`);
    console.log(`Change (2016-2012): ${diff.toFixed(2)}${pct === null ? '' : ` (${pct.toFixed(1)}%)`}`);

    if (m2016 < m2012) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('Error:', err && err.message ? err.message : err);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
